// W5 (part c), section 3 pick A on all three petrophysics tiers: the capstones
// move off the bundled typewell (which every panel opens on and every
// walkthrough worked) to IKPO-3, a well no panel loads. The learner downloads
// its LAS file from the capstone card and opens it in the page's well picker.
//
//   KEYS. The committed LAS is exactly what the case module builds, and the
//   eighteen keys are regenerated by parsing it with the vendored LAS parser
//   and running the panel lab, which calls the vendored petrophysics engines.
//   They must equal the spec and the committed migration.
//   LEAKS. No panel source, the page, the teaching lib or any lesson carries a
//   graded value in any string shape or a decimal inside a graded tolerance;
//   no panel imports the case; every panel's opening state (the typewell) lands
//   on no graded value.
//   LABEL. The W1 open-book label and lesson notes are gone.
//   CONTROLS. Every check goes red on a planted leak.
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import {
  REPO, renderingsOf, leaksIn, nearValuesIn, lessonsOf, sourcesOf, migrationFields, W1_LABEL, W1_LESSON_NOTE, TIERS,
} from '@/lib/w5cGuardKit';
import * as L from './typewellLab';
import { computeWorkflow, defaultParams, ADVANCED_GIVENS } from '@/lib/petrophysicsTeaching';
import { lasText, gradedKeys, caseWell, ZONES, WATER_LEG, PICKETT_WINDOW, LAB } from '../../../../../docs/graded-field-audit/w5c/petrophysics/case.mjs';

const SPEC = JSON.parse(fs.readFileSync(path.join(REPO, 'docs/graded-field-audit/w5c/petrophysics.json'), 'utf8'));
const FIELDS = JSON.parse(fs.readFileSync(path.join(REPO, 'docs/graded-field-audit/w5c/petrophysics/fields.json'), 'utf8'));
const LAS = path.join(REPO, 'src/content/capstone-cases/petrophysics/ikpo3.las');
const MIG = '20261028c_w5_petrophysics.sql';
const LIVE = Object.fromEntries(TIERS.map((t) => [t, migrationFields(MIG, 'petrophysics', t)]));
const ALL = TIERS.flatMap((t) => FIELDS[t].map((f) => ({ ...f, tier: t })));

const PANEL_DIR = 'src/components/course/panels/petrophysics';
const PAGE = 'src/pages/apps/PetrophysicsLearningPage.jsx';
const SOURCES = sourcesOf(PANEL_DIR, [PAGE, 'src/lib/petrophysicsTeaching.js']);
const LESSONS = lessonsOf('petrophysics');
const RENDER = ALL.filter((f) => !Number.isInteger(f.expected)).flatMap((f) => renderingsOf(f.key, f.expected));

describe('W5c petrophysics: the IKPO-3 well and its keys', () => {
  it('commits exactly the LAS the case module builds', () => {
    expect(fs.readFileSync(LAS, 'utf8')).toBe(lasText());
  });

  it('regenerates all eighteen keys from the committed LAS through the engine; they equal the spec and the migration', () => {
    const { fit, ...keys } = gradedKeys(fs.readFileSync(LAS, 'utf8'));
    expect(fit.nPoints).toBeGreaterThan(8);
    for (const t of TIERS) {
      expect(keys[t], t).toEqual(FIELDS[t]);
      expect(LIVE[t].fields.map((f) => [f.key, f.expected, f.tol]), t).toEqual(FIELDS[t].map((f) => [f.key, f.expected, f.tol]));
      expect(LIVE[t].prompt, t).toBe(SPEC.tiers[t].prompt);
      expect(LIVE[t].prompt, `${t}: W1 label`).not.toMatch(W1_LABEL);
      // every depth the learner must type is in the brief
      for (const d of [...ZONES.SAND_A, ...WATER_LEG]) expect(LIVE[t].prompt, `${t} ${d}`).toContain(String(d));
    }
    expect(LIVE.intermediate.prompt).toContain(`${PICKETT_WINDOW[0]} to ${PICKETT_WINDOW[1]} m`);
    for (const v of Object.values(LAB)) expect(LIVE.advanced.prompt, String(v)).toContain(String(v));
  });

  it('the well a learner builds from the LAS carries the float32 samples the engine parser stores', () => {
    const w = caseWell(fs.readFileSync(LAS, 'utf8'));
    expect(w.DEPTH).toHaveLength(201);
    expect(w.CURVES.RT.filter((x) => !Number.isFinite(x))).toHaveLength(1);
    expect(Math.fround(w.CURVES.RHOB[100])).toBe(w.CURVES.RHOB[100]);
  });
});

describe('W5c petrophysics: nothing prints an IKPO-3 answer before the learner works', () => {
  it('sweeps real sources and lessons', () => {
    expect(SOURCES.map((s) => s.file)).toEqual([
      `${PANEL_DIR}/PickettExplorer.jsx`, `${PANEL_DIR}/PorosityLab.jsx`, `${PANEL_DIR}/RwTriangulator.jsx`,
      `${PANEL_DIR}/ShalySwLab.jsx`, `${PANEL_DIR}/WellPicker.jsx`, `${PANEL_DIR}/panelKit.jsx`, `${PANEL_DIR}/typewellLab.js`,
      `${PANEL_DIR}/wellContext.jsx`, PAGE, 'src/lib/petrophysicsTeaching.js',
    ]);
    expect(LESSONS.length).toBeGreaterThan(60);
    expect(RENDER.length).toBeGreaterThan(40);
  });

  it('no source or lesson carries a graded value in any shape, or a decimal inside a graded tolerance', () => {
    const hits = [];
    for (const s of [...SOURCES, ...LESSONS]) {
      for (const h of leaksIn(s.text, RENDER)) hits.push(`${s.file}: ${h.key} as ${h.text} (${h.shape})`);
    }
    for (const l of LESSONS) for (const h of nearValuesIn(l.text, ALL)) hits.push(`${l.file}: ${h.text} within tol of ${h.key}`);
    expect(hits).toEqual([]);
  });

  it('no panel imports the case well; only the page does, to offer the download', () => {
    expect(SOURCES.filter((s) => /capstone-cases\/petrophysics/.test(s.text)).map((s) => s.file)).toEqual([PAGE]);
  });

  it('every panel and the page workflow, opening on the typewell, land on no graded value', () => {
    const seen = openingStateNumbers();
    expect(seen.length).toBeGreaterThan(20);
    expect(openingHits(seen)).toEqual([]);
  });

  it('the W1 open-book lesson note is gone from every tier', () => {
    expect(LESSONS.filter((l) => W1_LESSON_NOTE.test(l.text)).map((l) => l.file)).toEqual([]);
  });
});

describe('W5c petrophysics: negative controls', () => {
  it('a graded value planted at full float, nine digits or four decimals is caught', () => {
    const missed = [];
    for (const f of ALL.filter((x) => !Number.isInteger(x.expected))) {
      const r = RENDER.filter((x) => x.key === f.key);
      if (!r.length) continue;
      for (const shown of [String(f.expected), f.expected.toPrecision(9), f.expected.toFixed(4)]) {
        if (shown.length < 6) continue; // too short to be distinctive: the numeric sweeps cover it
        if (!leaksIn(`x = ${shown}`, r).length) missed.push(`${f.key}: ${shown}`);
      }
    }
    expect(missed).toEqual([]);
  });

  it('a panel that imports the case well, and an opening state on the case, are caught', () => {
    const planted = [...SOURCES, { file: `${PANEL_DIR}/Planted.jsx`, text: "import x from '@/content/capstone-cases/petrophysics';" }];
    expect(planted.filter((s) => /capstone-cases\/petrophysics/.test(s.text)).length).toBe(2);
    const f = ALL.find((x) => x.key === 'ikpo3_phind_avg_sand_a');
    const w = caseWell(fs.readFileSync(LAS, 'utf8'));
    const nd = L.porosityCurves({ rhoMa: L.TW.rho_ma, rhoFl: L.TW.rho_fl, dtMa: L.TW.dt_ma, dtFl: L.TW.dt_fl }, w).phiNdArr;
    const seen = [...openingStateNumbers(), { what: 'phiNdArr SAND_A', v: L.zoneMean(nd, w.ZONES.SAND_A, w) }];
    expect(openingHits(seen).some((h) => h.startsWith(`intermediate/${f.key}`))).toBe(true);
    // and a loose field's own quantity at the case value is caught like-for-like
    const g = ALL.find((x) => x.key === 'ikpo3_sand_a_net_m');
    expect(openingHits([{ what: 'SAND_A net_m', v: g.expected }]).some((h) => h.startsWith(`beginner/${g.key}`))).toBe(true);
  });
});

// A PRECISE graded field (tolerance within 1 percent of the value) may land on
// no opening number at all; a LOOSE one (a net pay to 0.75 m, a saturation to
// 0.02) is compared with the same quantity only, since it sits near half the
// numbers any panel shows and a coincidence there says nothing.
const LIKE = {
  ikpo3_sand_a_net_m: ['SAND_A net_m'], ikpo3_sand_a_phi_avg: ['SAND_A phi_avg'], ikpo3_sand_a_sw_avg: ['SAND_A sw_avg'],
  ikpo3_sand_b_net_m: ['SAND_B net_m'], ikpo3_sand_b_phi_avg: ['SAND_B phi_avg'], ikpo3_sand_b_sw_avg: ['SAND_B sw_avg'],
  ikpo3_sw_sim_sand_a: ['simandoux SAND_A'], ikpo3_sw_ind_sand_a: ['indonesia SAND_A'],
  ikpo3_sand_a_net_arps: ['SAND_A net_m'], ikpo3_sand_a_sw_avg_arps: ['SAND_A sw_avg'], ikpo3_sand_a_net_uncorrected: ['SAND_A net_m'],
};
function openingHits(seen) {
  const hits = [];
  for (const f of ALL) {
    const precise = f.tol <= 0.01 * Math.abs(f.expected);
    for (const x of seen) {
      if (!precise && !(LIKE[f.key] || []).includes(x.what)) continue;
      if (Math.abs(x.v - f.expected) <= f.tol) hits.push(`${f.tier}/${f.key} ~ ${x.what} ${x.v}`);
    }
  }
  return hits;
}

// Every number the page and panels show on the typewell before any input.
function openingStateNumbers() {
  const out = [];
  const add = (what, v) => { if (Number.isFinite(v)) out.push({ what, v }); };
  const wf = computeWorkflow(defaultParams());
  for (const z of ['SAND_A', 'SAND_B']) for (const k of ['net_m', 'gross_m', 'phi_avg', 'sw_avg', 'ntg']) add(`${z} ${k}`, wf.zones[z][k]);
  const tw = L.TYPEWELL;
  const por = L.porosityCurves({ rhoMa: L.TW.rho_ma, rhoFl: L.TW.rho_fl, dtMa: L.TW.dt_ma, dtFl: L.TW.dt_fl });
  for (const k of ['phiD', 'phiW', 'phiRhg', 'phiNdArr']) for (const z of ['SAND_A', 'SAND_B']) add(`${k} ${z}`, L.zoneMean(por[k], tw.ZONES[z]));
  const fit = L.fitPickett(por.phiNdArr, tw.WATER_LEG[0], tw.WATER_LEG[1]);
  add('pickett aRw', fit.aRw); add('pickett m', fit.m);
  const vsh = L.vshLinearCurve(L.TW.gr_clean, L.TW.gr_clay);
  for (const method of ['archie', 'simandoux', 'indonesia']) {
    const sw = L.swCurve({ method, phi: por.phiNdArr, vsh, rw: L.TW.rw, rsh: L.TW.rsh, a: L.TW.a, m: L.TW.m, n: L.TW.n });
    for (const z of ['SAND_A', 'SAND_B']) add(`${method} ${z}`, L.zoneMean(sw, tw.ZONES[z]));
  }
  const g = ADVANCED_GIVENS;
  const rwA = L.rwArps(g.rwSample, g.tSampleF, g.tFmF);
  add('arps', rwA); add('rwe', L.rweFromSsp(g.sspMv, g.rmfe, g.tFmF)); add('leg', L.waterLegMeanSw(rwA));
  return out;
}
